import{_ as e,a0 as o,w as p,s as P,I as t,x as i,a1 as r,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？ | LCTT x X-CMD","titleTemplate":false,"description":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？ | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？ | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20141226 Real-World WordPress Benchmarks with PHP5.5 PHP5.6 PHP-NG and HHVM","title":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？","tag":"201504","desc":""},"relativePath":"201504/20141226 Real-World WordPress Benchmarks with PHP5.5 PHP5.6 PHP-NG and HHVM.md","filePath":"[post].md"}'),H={name:"201504/20141226 Real-World WordPress Benchmarks with PHP5.5 PHP5.6 PHP-NG and HHVM.md"};function d(g,l,u,m,h,M){const s=o("Link");return p(),P("div",null,[l[16]||(l[16]=t("h1",{id:"php-5-5-php5-6-php-ng-和-hhvm-哪個性能更好",tabindex:"-1"},[i("PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？ "),t("a",{class:"header-anchor",href:"#php-5-5-php5-6-php-ng-和-hhvm-哪個性能更好","aria-label":"Permalink to “PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪個性能更好？”"},"​")],-1)),l[17]||(l[17]=t("p",null,[t("strong",null,"長篇摘要：在一個基於Vagrant的本地環境中，可能是某個錯誤的原因，導致HHVM測試結果很差；在HHVM夥伴們協助下，該原因仍在研究中！然而，在DigitalOcean的一個4GB虛擬機中，HHVM甚至蓋過了最新版的PHP-NG的風頭！")],-1)),l[18]||(l[18]=t("p",null,[t("img",{src:"https://kinsta.com/wp-content/uploads/2014/07/phphhvm.jpg",alt:""})],-1)),l[19]||(l[19]=t("p",null,[t("strong",null,"結論：它們反映出HHVM的功效更佳（在JIT熱啓動後），雖然出於某些原因，我們不能在所有裝備中獲取這些結果。")],-1)),t("p",null,[l[1]||(l[1]=i("如果你記得我們",-1)),r(s,{href:"https://kinsta.com/blog/hhvm-and-wordpress/"},{default:n(()=>[...l[0]||(l[0]=[i("在幾個月前寫過一篇文章",-1)])]),_:1}),l[2]||(l[2]=i("，那時WordPress 3.9表明是完全支持HHVM的，當時是那麼令我們歡欣鼓舞。最初的基準測試結果顯示，HHVM要比驅動着當前所有PHP構建的Zend引擎高級得多。後來，問題就出來了：",-1))]),l[20]||(l[20]=a(`<ul><li>HHVM只能以單個用户運行，這意味着（在共享環境中）安全性差了</li><li>HHVM在崩潰後不會自動重啓，而不幸的是，它至今仍然經常發生</li><li>HHVM在啓動時使用大量內存，雖然，它和同規模的PHP-FPM比較，單個請求的內存使用量更低</li></ul><p>很顯然，你不得不根據你的（或者更確切地説是你的站點）的需求採取折中方案，然而這值得嗎？切換到HHVM後，你期望獲得多少性能改善呢？</p><p>在Kinsta，我們真的想要測試所有新技術，並通常會優化這一切來為我們的客户提供最佳的環境。今天，我最終花了點時間來配置測試環境並進行了一些測試來對比兩個不同的構建，一個是全新出爐的WordPress安裝，另外一個則添加了大量內容的WooCommerce！為了計量腳本的運行時間，我只是簡單地添加了</p><pre><code>&lt;?php timer_stop(1); ?&gt;
</code></pre><p>這一行到footer.php的/body標記前。</p><p>這裏是配置環境的詳情：</p><ul><li>DigitalOcean 4GB 雨滴容器 (2 CPU核心, 4GB RAM)</li><li>Ubuntu 14.04, MariaDB10</li><li>測試站點： 已導入演示內容的Munditia主題，WooCommerce 2.1.12 &amp; WordPress 3.9.1</li><li>PHP 5.5.9, PHP 5.5.15, PHP 5.6.0 RC2, PHP-NG （20140718-git-6cc487d）和HHVM 3.2.0 （版本是PHP 5.6.99-hhvm）</li></ul><p><strong>沒有進一步大費周章，這些就是我的測試結果，數值越低越好，以秒為單位：</strong></p><h3 id="digitalocean-4gb-雨滴容器" tabindex="-1">DigitalOcean 4GB 雨滴容器 <a class="header-anchor" href="#digitalocean-4gb-雨滴容器" aria-label="Permalink to “DigitalOcean 4GB 雨滴容器”">​</a></h3><p>單位是秒，運行10次，越低越好</p><p>這裏有一個canvas的數據，發佈的時候需要截一個圖</p><p>看起來似乎PHP-NG在它首次運行後就獲得了峯值性能！HHVM需要更多幾次重載，但是它們的性能貌似差不多！我等不及PHP-NG合併到開發主幹了！：）</p><p>一分鐘命中數，越高越好。</p><p>這裏有一個canvas的數據，發佈的時候需要截一個圖</p><p><strong>PHP 5.5.15禁用OpCache</strong></p><ul><li>執行： <strong>236 hits</strong></li><li>可用性： 100.00 %</li><li>消耗時間： 59.03 secs</li><li>傳輸的數據： 2.40 MB</li><li>回應時間： 2.47 secs</li><li>執行率： 4.00 trans/sec</li><li>吞吐量： 0.04 MB/sec</li><li>併發數： 9.87</li><li>成功的執行： 236</li><li>失敗的執行： 0</li><li>最長執行： 4.44</li><li>最短執行： 0.48</li></ul><p><strong>PHP 5.5.15啓用OpCache</strong></p><ul><li>執行： <strong>441 hits</strong></li><li>可用性： 100.00 %</li><li>消耗時間： 59.55 secs</li><li>傳輸的數據： 4.48 MB</li><li>回應時間： 1.34 secs</li><li>執行率： 7.41 trans/sec</li><li>吞吐量： 0.08 MB/sec</li><li>併發數： 9.91</li><li>成功的執行： 441</li><li>失敗的執行： 0</li><li>最長執行： 2.19</li><li>最短執行： 0.64</li></ul><p><strong>PHP 5.6 RC2禁用OpCache</strong></p><ul><li>執行： <strong>207 hits</strong></li><li>可用性： 100.00 %</li><li>消耗時間： 59.87 secs</li><li>傳輸的數據： 2.10 MB</li><li>回應時間： 2.80 secs</li><li>執行率： 3.46 trans/sec</li><li>吞吐量： 0.04 MB/sec</li><li>併發數： 9.68</li><li>成功的執行： 207</li><li>失敗的執行： 0</li><li>最長執行： 3.65</li><li>最短執行： 0.54</li></ul><p><strong>PHP 5.6 RC2啓用OpCache</strong></p><ul><li>執行： <strong>412 hits</strong></li><li>可用性： 100.00 %</li><li>消耗時間： 59.03 secs</li><li>傳輸的數據： 4.18 MB</li><li>回應時間： 1.42 secs</li><li>執行率： 6.98 trans/sec</li><li>吞吐量： 0.07 MB/sec</li><li>併發數： 9.88</li><li>成功的執行： 412</li><li>失敗的執行： 0</li><li>最長執行： 1.93</li><li>最短執行： 0.34</li></ul><p><strong>HHVM 3.2.0（版本是PHP 5.6.99-hhvm）</strong></p><ul><li>執行： <strong>955 hits</strong></li><li>可用性： 100.00 %</li><li>消耗時間： 59.69 secs</li><li>傳輸的數據： 9.18 MB</li><li>回應時間： 0.62 secs</li><li>執行率： 16.00 trans/sec</li><li>吞吐量： 0.15 MB/sec</li><li>併發數： 9.94</li><li>成功的執行： 955</li><li>失敗的執行： 0</li><li>最長執行： 0.85</li><li>最短執行： 0.23</li></ul><p><strong>PHP-NG啓用OpCache（構建: Jul 29 2014）</strong></p><ul><li>執行： <strong>849 hits</strong></li><li>可用性： 100.00 %</li><li>消耗時間： 59.88 secs</li><li>傳輸的數據： 8.63 MB</li><li>回應時間： 0.70 secs</li><li>執行率： 14.18 trans/sec</li><li>吞吐量： 0.14 MB/sec</li><li>併發數： 9.94</li><li>成功的執行： 849</li><li>失敗的執行： 0</li><li>最長執行： 1.06</li><li>最短執行： 0.13</li></ul><p><strong>注意：這裏節略了前一次的測試結果（有誤），如感興趣請訪問原文查看。</strong></p><hr>`,28)),t("p",null,[l[4]||(l[4]=i("via: ",-1)),r(s,{href:"https://kinsta.com/blog/real-world-wordpress-benchmarks-with-php5-5-php5-6-php-ng-and-hhvm/"},{default:n(()=>[...l[3]||(l[3]=[i("https://kinsta.com/blog/real-world-wordpress-benchmarks-with-php5-5-php5-6-php-ng-and-hhvm/",-1)])]),_:1})]),t("p",null,[l[8]||(l[8]=i("作者：",-1)),r(s,{href:"https://kinsta.com/blog/author/kinstadmin/"},{default:n(()=>[...l[5]||(l[5]=[i("Mark Gavalda",-1)])]),_:1}),l[9]||(l[9]=i(" 譯者：",-1)),r(s,{href:"https://github.com/GOLinux"},{default:n(()=>[...l[6]||(l[6]=[i("GOLinux",-1)])]),_:1}),l[10]||(l[10]=i(" 校對：",-1)),r(s,{href:"https://github.com/wxy"},{default:n(()=>[...l[7]||(l[7]=[i("wxy",-1)])]),_:1})]),t("p",null,[l[13]||(l[13]=i("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[11]||(l[11]=[i("LCTT",-1)])]),_:1}),l[14]||(l[14]=i(" 原創翻譯，",-1)),r(s,{href:"http://linux.cn/"},{default:n(()=>[...l[12]||(l[12]=[i("Linux中國",-1)])]),_:1}),l[15]||(l[15]=i(" 榮譽推出",-1))])])}const B=e(H,[["render",d]]);export{f as __pageData,B as default};
